   152	
   153	int board_mipi_dsi_panel_reset(void)
   154	{
   155	  int ret;
   156	
   157	  syslog(LOG_INFO,
   158	         "INFO: P4X DSI panel reset configure gpio=%d active_low=1\n",
   159	         BOARD_MIPI_DSI_PANEL_RESET_GPIO);
   160	  ret = esp_configgpio(BOARD_MIPI_DSI_PANEL_RESET_GPIO, OUTPUT);
   161	  if (ret < 0)
   162	    {
   163	      syslog(LOG_ERR, "ERROR: P4X DSI panel reset gpio configure ret=%d\n",
   164	             ret);
   165	      return -EIO;
   166	    }
   167	
   168	  /* RST_LCD is active low on the P4X LCD adapter. */
   169	
   170	  syslog(LOG_INFO, "INFO: P4X DSI panel reset assert delay_us=%d\n",
   171	         BOARD_MIPI_DSI_RESET_ASSERT_US);
   172	  esp_gpiowrite(BOARD_MIPI_DSI_PANEL_RESET_GPIO, false);
   173	  nxsig_usleep(BOARD_MIPI_DSI_RESET_ASSERT_US);
   174	
   175	  syslog(LOG_INFO, "INFO: P4X DSI panel reset release delay_us=%d\n",
   176	         BOARD_MIPI_DSI_RESET_RELEASE_US);
   177	  esp_gpiowrite(BOARD_MIPI_DSI_PANEL_RESET_GPIO, true);
   178	  ret = nxsig_usleep(BOARD_MIPI_DSI_RESET_RELEASE_US);
   179	  if (ret < 0)
   180	    {
   181	      syslog(LOG_ERR, "ERROR: P4X DSI panel reset release ret=%d\n", ret);
   182	      return ret;
   183	    }
   184	
   185	  syslog(LOG_INFO, "INFO: P4X DSI panel reset complete\n");
   186	  return OK;
   187	}
