   192	/****************************************************************************
   193	 * Name: board_mipi_dsi_fill_colour_bars
   194	 ****************************************************************************/
   195	
   196	static void board_mipi_dsi_fill_colour_bars(FAR uint8_t *frame_buffer)
   197	{
   198	  static const uint8_t colours[BOARD_MIPI_DSI_COLOUR_BAR_COUNT][3] =
   199	  {
   200	    {0xff, 0xff, 0xff}, /* White */
   201	    {0xff, 0xff, 0x00}, /* Yellow */
   202	    {0x00, 0xff, 0xff}, /* Cyan */
   203	    {0x00, 0xff, 0x00}, /* Green */
   204	    {0xff, 0x00, 0xff}, /* Magenta */
   205	    {0xff, 0x00, 0x00}, /* Red */
   206	    {0x00, 0x00, 0xff}, /* Blue */
   207	    {0x00, 0x00, 0x00}, /* Black */
   208	  };
   209	
   210	  FAR uint8_t *pixel = frame_buffer;
   211	  uint32_t x;
   212	  uint32_t y;
   213	  uint32_t bar;
   214	
   215	  for (y = 0; y < BOARD_MIPI_DSI_VACTIVE; y++)
   216	    {
   217	      for (x = 0; x < BOARD_MIPI_DSI_HACTIVE; x++)
   218	        {
   219	          bar = x * BOARD_MIPI_DSI_COLOUR_BAR_COUNT /
   220	                BOARD_MIPI_DSI_HACTIVE;
   221	          pixel[0] = colours[bar][0];
   222	          pixel[1] = colours[bar][1];
   223	          pixel[2] = colours[bar][2];
   224	          pixel += BOARD_MIPI_DSI_BYTES_PER_PIXEL;
   225	        }
   226	    }
   227	}
