   229	/****************************************************************************
   230	 * Name: board_mipi_dsi_allocate_frame_buffer
   231	 ****************************************************************************/
   232	
   233	static int board_mipi_dsi_allocate_frame_buffer(void)
   234	{
   235	  FAR void *frame_buffer;
   236	  int ret;
   237	
   238	  if (g_board_mipi_dsi_frame_buffer != NULL)
   239	    {
   240	      return OK;
   241	    }
   242	
   243	  /* ESP HAL heap/cache APIs are deliberately contained by the P4 chip
   244	   * adapter.  The board owns the pixel data and lifetime only.
   245	   */
   246	
   247	  ret = esp_mipi_dsi_dma_buffer_allocate(BOARD_MIPI_DSI_FRAME_BYTES,
   248	                                         &frame_buffer);
   249	  if (ret < 0)
   250	    {
   251	      syslog(LOG_ERR,
   252	             "ERROR: P4X DSI DMA frame allocation bytes=%zu ret=%d\n",
   253	             BOARD_MIPI_DSI_FRAME_BYTES, ret);
   254	      return ret;
   255	    }
   256	
   257	  g_board_mipi_dsi_frame_buffer = frame_buffer;
   258	  board_mipi_dsi_fill_colour_bars(g_board_mipi_dsi_frame_buffer);
   259	  ret = esp_mipi_dsi_dma_buffer_sync_for_device(
   260	    g_board_mipi_dsi_frame_buffer, BOARD_MIPI_DSI_FRAME_BYTES);
   261	  if (ret < 0)
   262	    {
   263	      syslog(LOG_ERR, "ERROR: P4X DSI DMA frame cache sync ret=%d\n", ret);
   264	      esp_mipi_dsi_dma_buffer_free(g_board_mipi_dsi_frame_buffer);
   265	      g_board_mipi_dsi_frame_buffer = NULL;
   266	      return ret;
   267	    }
   268	
   269	  syslog(LOG_INFO,
   270	         "INFO: P4X DSI DMA colour bars ready buffer=%p bytes=%zu\n",
   271	         g_board_mipi_dsi_frame_buffer, BOARD_MIPI_DSI_FRAME_BYTES);
   272	  return OK;
   273	}
