    94	/* EK79007 vendor init sequence (2-lane pad control + gamma/timing
    95	 * registers + sleep-out), taken from the panel vendor reference.
    96	 */
    97	
    98	static const struct ek79007_cmd_s g_ek79007_init[] =
    99	{
   100	  { 0xb2, 0x10, 1, 0 },     /* Pad control: 2-lane MIPI */
   101	  { 0x80, 0x8b, 1, 0 },
   102	  { 0x81, 0x78, 1, 0 },
   103	  { 0x82, 0x84, 1, 0 },
   104	  { 0x83, 0x88, 1, 0 },
   105	  { 0x84, 0xa8, 1, 0 },
   106	  { 0x85, 0xe3, 1, 0 },
   107	  { 0x86, 0x88, 1, 0 },
   108	  { 0x11, 0x00, 0, 120 },   /* Sleep out */
   109	};
   110	
   111	static const struct esp_mipi_dsi_video_s g_panel_timing =
   112	{
   113	  .h_size      = LCD_XRES,
   114	  .v_size      = LCD_YRES,
   115	  .hsw         = 10,
   116	  .hbp         = 160,
   117	  .hfp         = 160,
   118	  .vsw         = 1,
   119	  .vbp         = 23,
   120	  .vfp         = 12,
   121	  .dpi_clk_mhz = 52,
   122	};
   123	
   124	static struct fb_vtable_s g_fb_vtable =
   125	{
   126	  .getvideoinfo = esp_getvideoinfo,
   127	  .getplaneinfo = esp_getplaneinfo,
   128	#ifdef CONFIG_FB_UPDATE
   129	  .updatearea   = esp_updatearea,
   130	#endif
   131	};
   132	
   133	/* Double buffering: LVGL and other clients render into the back buffer
   134	 * (g_fb, exposed via the fb interface) while the DSI DMA continuously
   135	 * scans out the front buffer.  On update only the dirty rows are copied
   136	 * across and cache-synced, which shrinks the tearing window from the
   137	 * whole rendering time down to a few milliseconds of row copy.
   138	 */
   139	
   140	static uint8_t *g_fb;        /* Back buffer, exposed to clients */
   141	static uint8_t *g_fb_front;  /* Front buffer, scanned out by the DMA */
   142	static bool g_lcd_initialized;
   143	
   144	/****************************************************************************
   145	 * Private Functions
   146	 ****************************************************************************/
   147	
   148	static int esp_getvideoinfo(struct fb_vtable_s *vtable,
   149	                            struct fb_videoinfo_s *vinfo)
   150	{
   151	  if (vinfo == NULL)
   152	    {
   153	      return -EINVAL;
   154	    }
   155	
   156	  vinfo->fmt     = FB_FMT_RGB16_565;
   157	  vinfo->xres    = LCD_XRES;
   158	  vinfo->yres    = LCD_YRES;
   159	  vinfo->nplanes = 1;
   160	  return OK;
   161	}
   162	
   163	static int esp_getplaneinfo(struct fb_vtable_s *vtable, int planeno,
   164	                            struct fb_planeinfo_s *pinfo)
   165	{
   166	  if (pinfo == NULL || planeno != 0)
   167	    {
   168	      return -EINVAL;
   169	    }
   170	
   171	  memset(pinfo, 0, sizeof(*pinfo));
   172	  pinfo->fbmem   = g_fb;
   173	  pinfo->fblen   = LCD_FB_SIZE;
   174	  pinfo->stride  = LCD_STRIDE;
   175	  pinfo->display = 0;
   176	  pinfo->bpp     = LCD_BPP;
   177	  return OK;
   178	}
   179	
   180	#ifdef CONFIG_FB_UPDATE
   181	static int esp_updatearea(struct fb_vtable_s *vtable,
   182	                          const struct fb_area_s *area)
   183	{
   184	  /* Write back only the dirty rows (rows are contiguous in memory), so
   185	   * frequent small UI updates don't pay for a whole-framebuffer sync.
   186	   */
   187	
   188	  size_t start = (size_t)area->y * LCD_STRIDE;
   189	  size_t len   = (size_t)area->h * LCD_STRIDE;
   190	
   191	  if (start >= LCD_FB_SIZE)
   192	    {
   193	      return OK;
   194	    }
   195	
   196	  if (start + len > LCD_FB_SIZE)
   197	    {
   198	      len = LCD_FB_SIZE - start;
   199	    }
   200	
   201	  memcpy(g_fb_front + start, g_fb + start, len);
   202	  esp_mipi_dsi_flush(g_fb_front + start, len);
   203	  return OK;
   204	}
   205	#endif
