   211	/****************************************************************************
   212	 * Name: up_fbinitialize
   213	 *
   214	 * Description:
   215	 *   Power up and initialize the EK79007 DSI panel, allocate the PSRAM
   216	 *   framebuffer and start the continuous DPI video stream.
   217	 *
   218	 ****************************************************************************/
   219	
   220	int up_fbinitialize(int display)
   221	{
   222	  uint8_t pwr = 0;
   223	  uint8_t id1 = 0;
   224	  int rd;
   225	  int ret;
   226	  size_t i;
   227	
   228	  if (g_lcd_initialized)
   229	    {
   230	      return OK;
   231	    }
   232	
   233	  /* Backlight off during panel bring-up, then hardware reset pulse */
   234	
   235	  esp_configgpio(LCD_GPIO_BL, OUTPUT);
   236	  esp_gpiowrite(LCD_GPIO_BL, false);
   237	
   238	  esp_configgpio(LCD_GPIO_RST, OUTPUT);
   239	  esp_gpiowrite(LCD_GPIO_RST, false);
   240	  nxsig_usleep(10 * 1000);
   241	  esp_gpiowrite(LCD_GPIO_RST, true);
   242	  nxsig_usleep(20 * 1000);
   243	
   244	  ret = esp_mipi_dsi_init(LCD_DSI_LANES, LCD_DSI_RATE_MBPS,
   245	                          LCD_DPHY_LDO_CHAN, LCD_DPHY_LDO_MV);
   246	  if (ret < 0)
   247	    {
   248	      lcderr("ERROR: esp_mipi_dsi_init failed: %d\n", ret);
   249	      return ret;
   250	    }
   251	
   252	  /* Panel initialization over low-power DCS commands */
   253	
   254	  for (i = 0; i < sizeof(g_ek79007_init) / sizeof(g_ek79007_init[0]); i++)
   255	    {
   256	      const struct ek79007_cmd_s *c = &g_ek79007_init[i];
   257	
   258	      ret = esp_mipi_dsi_dcs_write(c->cmd, &c->data, c->data_len);
   259	      if (ret < 0)
   260	        {
   261	          lcderr("ERROR: DCS 0x%02x failed: %d\n", c->cmd, ret);
   262	          return ret;
   263	        }
   264	
   265	      if (c->delay_ms > 0)
   266	        {
   267	          nxsig_usleep((useconds_t)c->delay_ms * 1000);
   268	        }
   269	    }
   270	
   271	  /* Panel presence check: a DCS read only succeeds if a powered panel
   272	   * responds on the DSI link.  RDDPM (0x0a) returns the power mode and
   273	   * RDID1 (0xda) the manufacturer ID.
   274	   */
   275	
   276	  rd = esp_mipi_dsi_dcs_read(0x0a, &pwr, 1);
   277	  if (rd > 0)
   278	    {
   279	      esp_mipi_dsi_dcs_read(0xda, &id1, 1);
   280	      syslog(LOG_INFO,
   281	             "LCD: panel detected on DSI (power 0x%02x, ID1 0x%02x)\n",
