   422	int esp_mipi_dsi_dpi_start(const struct esp_mipi_dsi_video_s *vt,
   423	                           uint8_t *fb)
   424	{
   425	  struct esp_dsi_dev_s *dev = &g_dsi_dev;
   426	  mipi_dsi_hal_context_t *hal = &dev->hal;
   427	  dw_gdma_channel_alloc_config_t dma_alloc_config;
   428	  dw_gdma_block_transfer_config_t dma_transfer_config;
   429	  soc_module_clk_t dpi_clk;
   430	  uint32_t dpi_clk_src_freq_hz = 0;
   431	  uint32_t dpi_div;
   432	
   433	  if (!dev->initialized || vt == NULL || fb == NULL)
   434	    {
   435	      return -EINVAL;
   436	    }
   437	
   438	  dev->fb = fb;
   439	  dev->fb_size = (size_t)vt->h_size * vt->v_size * 2;
   440	
   441	  /* Route and enable the DPI pixel clock */
   442	
   443	  dpi_clk = (soc_module_clk_t)MIPI_DSI_DPI_CLK_SRC_DEFAULT;
   444	
   445	  esp_clk_tree_src_get_freq_hz(dpi_clk,
   446	                               ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
   447	                               &dpi_clk_src_freq_hz);
   448	  dpi_div = mipi_dsi_hal_host_dpi_calculate_divider(
   449	                hal, dpi_clk_src_freq_hz / 1000000.0f,
   450	                (float)vt->dpi_clk_mhz);
   451	  esp_clk_tree_enable_src(dpi_clk, true);
   452	
   453	  PERIPH_RCC_ATOMIC()
   454	    {
   455	      mipi_dsi_ll_set_dpi_clock_source(DSI_BUS_ID,
   456	                                       MIPI_DSI_DPI_CLK_SRC_DEFAULT);
   457	      mipi_dsi_ll_set_dpi_clock_div(DSI_BUS_ID, dpi_div);
   458	      mipi_dsi_ll_enable_dpi_clock(DSI_BUS_ID, true);
   459	    }
   460	
   461	  /* Allocate the DW-GDMA channel that feeds the DSI bridge.  Both ends
   462	   * use the hardware auto-reload block mode: the same whole-frame block
   463	   * restarts forever without any CPU/interrupt involvement.
   464	   */
   465	
   466	  memset(&dma_alloc_config, 0, sizeof(dma_alloc_config));
   467	  dma_alloc_config.src.block_transfer_type = DW_GDMA_BLOCK_TRANSFER_RELOAD;
   468	  dma_alloc_config.src.role = DW_GDMA_ROLE_MEM;
   469	  dma_alloc_config.src.handshake_type = DW_GDMA_HANDSHAKE_HW;
   470	  dma_alloc_config.src.num_outstanding_requests = 5;
   471	  dma_alloc_config.dst.block_transfer_type = DW_GDMA_BLOCK_TRANSFER_RELOAD;
   472	  dma_alloc_config.dst.role = DW_GDMA_ROLE_PERIPH_DSI;
   473	  dma_alloc_config.dst.handshake_type = DW_GDMA_HANDSHAKE_HW;
   474	  dma_alloc_config.dst.num_outstanding_requests = 2;
   475	  dma_alloc_config.flow_controller = DW_GDMA_FLOW_CTRL_SELF;
   476	  dma_alloc_config.chan_priority = 1;
   477	
   478	  if (dw_gdma_new_channel(&dma_alloc_config, &dev->dma_chan) != 0)
   479	    {
   480	      lcderr("ERROR: failed to create DW-GDMA channel\n");
   481	      return -ENOMEM;
   482	    }
   483	
   484	  /* DPI host configuration: RGB565 video, burst mode with sync pulses */
   485	
   486	  mipi_dsi_host_ll_dpi_set_vcid(hal->host, DSI_VIRTUAL_CHANNEL);
   487	  mipi_dsi_host_ll_dpi_set_color_coding(hal->host, LCD_COLOR_FMT_RGB565, 0);
   488	  mipi_dsi_host_ll_dpi_set_timing_polarity(hal->host, false, false, false,
   489	                                           false, false);
   490	  mipi_dsi_host_ll_dpi_enable_lp_horizontal_timing(hal->host, true, true);
   491	  mipi_dsi_host_ll_dpi_enable_lp_vertical_timing(hal->host, true, true,
   492	                                                 true, true);
   493	  mipi_dsi_host_ll_dpi_enable_lp_command(hal->host, true);
   494	  mipi_dsi_host_ll_dpi_enable_frame_ack(hal->host, true);
   495	  mipi_dsi_host_ll_dpi_set_video_burst_type(hal->host,
   496	      MIPI_DSI_LL_VIDEO_BURST_WITH_SYNC_PULSES);
   497	  mipi_dsi_host_ll_dpi_set_video_packet_pixel_num(hal->host, vt->h_size);
   498	  mipi_dsi_host_ll_dpi_set_trunks_num(hal->host, 0);
   499	  mipi_dsi_host_ll_dpi_set_null_packet_size(hal->host, 0);
   500	  mipi_dsi_hal_host_dpi_set_horizontal_timing(hal, vt->hsw, vt->hbp,
   501	                                              vt->h_size, vt->hfp);
   502	  mipi_dsi_hal_host_dpi_set_vertical_timing(hal, vt->vsw, vt->vbp,
   503	                                            vt->v_size, vt->vfp);
   504	
   505	  /* DSI bridge: frame geometry, color format and DMA flow control */
   506	
   507	  mipi_dsi_brg_ll_set_num_pixel_bits(hal->bridge,
   508	      (uint32_t)vt->h_size * vt->v_size * 16);
   509	  mipi_dsi_brg_ll_set_underrun_discard_count(hal->bridge, vt->h_size);
   510	  mipi_dsi_brg_ll_set_input_color_format(hal->bridge, LCD_COLOR_FMT_RGB565);
   511	  mipi_dsi_brg_ll_set_output_color_format(hal->bridge, LCD_COLOR_FMT_RGB565,
   512	                                          0);
   513	  mipi_dsi_brg_ll_set_flow_controller(hal->bridge,
   514	                                      MIPI_DSI_LL_FLOW_CONTROLLER_DMA);
   515	  mipi_dsi_brg_ll_set_multi_block_number(hal->bridge, 1);
   516	  mipi_dsi_brg_ll_set_burst_len(hal->bridge, 256);
   517	  mipi_dsi_brg_ll_set_empty_threshold(hal->bridge, 1024 - 256);
   518	  mipi_dsi_brg_ll_enable(hal->bridge, true);
   519	  mipi_dsi_brg_ll_update_dpi_config(hal->bridge);
   520	
   521	  /* One DMA block carries the whole frame: fb -> DSI bridge FIFO */
   522	
   523	  memset(&dma_transfer_config, 0, sizeof(dma_transfer_config));
   524	  dma_transfer_config.src.addr = (uint32_t)(uintptr_t)fb;
   525	  dma_transfer_config.src.burst_mode = DW_GDMA_BURST_MODE_INCREMENT;
   526	  dma_transfer_config.src.burst_items = DW_GDMA_BURST_ITEMS_512;
   527	  dma_transfer_config.src.burst_len = 16;
   528	  dma_transfer_config.src.width = DW_GDMA_TRANS_WIDTH_64;
   529	  dma_transfer_config.dst.addr = MIPI_DSI_BRG_MEM_BASE;
   530	  dma_transfer_config.dst.burst_mode = DW_GDMA_BURST_MODE_FIXED;
   531	  dma_transfer_config.dst.burst_items = DW_GDMA_BURST_ITEMS_256;
   532	  dma_transfer_config.dst.burst_len = 16;
   533	  dma_transfer_config.dst.width = DW_GDMA_TRANS_WIDTH_64;
   534	  dma_transfer_config.size = dev->fb_size * 8 / 64;
   535	
   536	  dw_gdma_channel_config_transfer(dev->dma_chan, &dma_transfer_config);
   537	  dw_gdma_channel_enable_ctrl(dev->dma_chan, true);
   538	
   539	  /* Switch the host to video mode and open the bridge DPI output */
   540	
   541	  mipi_dsi_host_ll_enable_video_mode(hal->host, true);
   542	  mipi_dsi_brg_ll_enable_dpi_output(hal->bridge, true);
   543	  mipi_dsi_brg_ll_update_dpi_config(hal->bridge);
   544	
   545	  return OK;
   546	}
