  1741	int esp_mipi_dsi_video_dma_start(
  1742	  FAR struct mipi_dsi_host *host,
  1743	  FAR const struct esp_mipi_dsi_video_dma_config_s *config)
  1744	{
  1745	#ifdef CONFIG_ESPRESSIF_MIPI_DSI_VIDEO_DMA
  1746	  FAR struct esp_mipi_dsi_s *priv = &g_esp_mipi_dsi;
  1747	  lcd_color_format_t input_format;
  1748	  lcd_color_format_t output_format;
  1749	  size_t bytes_per_pixel;
  1750	  size_t output_bytes_per_pixel;
  1751	  size_t required_bytes;
  1752	  int ret;
  1753	
  1754	  if (host != &priv->host || config == NULL ||
  1755	      !esp_mipi_dsi_video_timing_valid(config->channel, config->hactive,
  1756	                                        config->vactive,
  1757	                                        config->pixel_clock_hz) ||
  1758	      config->frame_buffer == NULL)
  1759	    {
  1760	      return -EINVAL;
  1761	    }
  1762	
  1763	  ret = esp_mipi_dsi_video_color_format(config->input_format,
  1764	                                        &input_format, &bytes_per_pixel);
  1765	  if (ret < 0)
  1766	    {
  1767	      return ret;
  1768	    }
  1769	
  1770	  ret = esp_mipi_dsi_video_color_format(config->output_format,
  1771	                                        &output_format,
  1772	                                        &output_bytes_per_pixel);
  1773	  if (ret < 0)
  1774	    {
  1775	      return ret;
  1776	    }
  1777	
  1778	  if (output_bytes_per_pixel == 0)
  1779	    {
  1780	      return -EINVAL;
  1781	    }
  1782	
  1783	  if (config->hactive > SIZE_MAX / config->vactive ||
  1784	      (size_t)config->hactive * config->vactive >
  1785	        SIZE_MAX / bytes_per_pixel)
  1786	    {
  1787	      return -EOVERFLOW;
  1788	    }
  1789	
  1790	  required_bytes = (size_t)config->hactive * config->vactive *
  1791	                   bytes_per_pixel;
  1792	  if (config->frame_buffer_bytes < required_bytes ||
  1793	      (required_bytes % ESP_MIPI_DSI_DMA_TRANSFER_WIDTH_BYTES) != 0)
  1794	    {
  1795	      return -EINVAL;
  1796	    }
  1797	
  1798	  ret = nxmutex_lock(&priv->lock);
  1799	  if (ret < 0)
  1800	    {
  1801	      return ret;
  1802	    }
  1803	
  1804	  if (!priv->ready)
  1805	    {
  1806	      ret = -ESHUTDOWN;
  1807	      goto errout_unlock;
  1808	    }
  1809	
  1810	  if (priv->video_running)
  1811	    {
  1812	      ret = -EALREADY;
  1813	      goto errout_unlock;
  1814	    }
  1815	
  1816	  ret = esp_mipi_dsi_enable_dpi_clock(priv, config->pixel_clock_hz);
  1817	  if (ret < 0)
  1818	    {
  1819	      goto errout_unlock;
  1820	    }
  1821	
  1822	  /* The bridge timing registers require both bridge clocks before their
  1823	   * configuration is written.  Unlike M2a, M2b uses DW-GDMA as the actual
  1824	   * pixel producer and therefore does not select the Host pattern source.
  1825	   */
  1826	
  1827	  mipi_dsi_brg_ll_force_enable_reg_clock(priv->hal.bridge, true);
  1828	  mipi_dsi_brg_ll_enable_ref_clock(priv->hal.bridge, true);
  1829	  esp_mipi_dsi_video_configure_host(
  1830	    priv, config->channel, config->hactive, config->hsync,
  1831	    config->hback_porch, config->hfront_porch, config->vactive,
  1832	    config->vsync, config->vback_porch, config->vfront_porch,
  1833	    config->hsync_active_low, config->vsync_active_low, output_format);
  1834	  mipi_dsi_host_ll_dpi_set_pattern_type(priv->hal.host,
  1835	                                        MIPI_DSI_PATTERN_NONE);
  1836	  esp_mipi_dsi_video_configure_bridge(
  1837	    priv, config->hactive, config->vactive,
  1838	    bytes_per_pixel * 8, input_format, output_format,
  1839	    MIPI_DSI_LL_FLOW_CONTROLLER_DMA);
  1840	  mipi_dsi_brg_ll_set_multi_block_number(priv->hal.bridge, 1);
  1841	  mipi_dsi_brg_ll_set_burst_len(priv->hal.bridge,
  1842	                                 ESP_MIPI_DSI_DMA_BURST_WORDS);
  1843	  mipi_dsi_brg_ll_set_empty_threshold(priv->hal.bridge,
  1844	                                       ESP_MIPI_DSI_DMA_EMPTY_THRESHOLD);
  1845	  mipi_dsi_brg_ll_enable_dpi_output(priv->hal.bridge, false);
  1846	
  1847	  ret = esp_mipi_dsi_video_dma_prepare(priv, config->frame_buffer,
  1848	                                       required_bytes);
  1849	  if (ret < 0)
  1850	    {
  1851	      goto errout_video;
  1852	    }
  1853	
  1854	  ret = esp_mipi_dsi_bridge_interrupt_prepare(priv);
  1855	  if (ret < 0)
  1856	    {
  1857	      goto errout_video;
  1858	    }
  1859	
  1860	  mipi_dsi_brg_ll_enable(priv->hal.bridge, true);
  1861	  mipi_dsi_brg_ll_update_dpi_config(priv->hal.bridge);
  1862	  mipi_dsi_host_ll_enable_bta(priv->hal.host, false);
  1863	  mipi_dsi_host_ll_set_clock_lane_state(
  1864	    priv->hal.host, MIPI_DSI_LL_CLOCK_LANE_STATE_AUTO);
  1865	
  1866	  /* The Bridge can request pixels as soon as DPI output is enabled.  Match
  1867	   * the ESP-IDF DPI panel ordering: make the GDMA producer runnable before
  1868	   * enabling Host video mode and Bridge output.
  1869	   */
  1870	
  1871	  dw_gdma_ll_channel_enable(priv->dma_dev, ESP_MIPI_DSI_DMA_CHANNEL, true);
  1872	  mipi_dsi_host_ll_enable_video_mode(priv->hal.host, true);
  1873	  mipi_dsi_brg_ll_enable_dpi_output(priv->hal.bridge, true);
  1874	  mipi_dsi_brg_ll_update_dpi_config(priv->hal.bridge);
  1875	  mipi_dsi_brg_ll_enable_interrupt(
  1876	    priv->hal.bridge, MIPI_DSI_BRG_LL_EVENT_UNDERRUN, true);
  1877	  syslog(LOG_INFO, "INFO: MIPI-DSI Bridge underrun interrupt enabled\n");
