  1879	  priv->video_running = true;
  1880	  esp_mipi_dsi_dump_video_state(priv, "dma-started");
  1881	  esp_mipi_dsi_dump_dma_status(priv, "dma-started");
  1882	  syslog(LOG_INFO,
  1883	         "INFO: MIPI-DSI DPI DMA started channel=%u size=%ux%u "
  1884	         "pixel_clock_hz=%" PRIu32 " frame_bytes=%zu\n",
  1885	         config->channel, config->hactive, config->vactive,
  1886	         config->pixel_clock_hz, required_bytes);
  1887	  nxmutex_unlock(&priv->lock);
  1888	  return OK;
  1889	
  1890	errout_video:
  1891	  mipi_dsi_host_ll_enable_video_mode(priv->hal.host, false);
  1892	  mipi_dsi_brg_ll_enable_dpi_output(priv->hal.bridge, false);
  1893	  esp_mipi_dsi_video_dma_release(priv);
  1894	  mipi_dsi_brg_ll_enable(priv->hal.bridge, false);
  1895	  mipi_dsi_brg_ll_enable_ref_clock(priv->hal.bridge, false);
  1896	  mipi_dsi_brg_ll_force_enable_reg_clock(priv->hal.bridge, false);
  1897	  esp_mipi_dsi_disable_dpi_clock(priv);
  1898	errout_unlock:
  1899	  nxmutex_unlock(&priv->lock);
  1900	  return ret;
