    39	#define EK79007_MADCTL_DEFAULT        0x01
    40	
    41	/****************************************************************************
    42	 * Public Types
    43	 ****************************************************************************/
    44	
    45	/* A vendor DCS command used during panel initialization.  A command with a
    46	 * non-zero data_len must have a non-NULL data pointer.  delay_ms is applied
    47	 * after the command has been accepted by the DSI host.
