    55	  uint16_t delay_ms;
    56	};
    57	
    58	struct esp_mipi_dsi_dpi_panel_s;
    59	struct esp_mipi_dsi_dpi_panel_config_s;
    60	
    61	/* Panel and DSI link configuration.  The timing pointer is descriptive
    62	 * metadata for the future DSI host.  The panel-control driver does not
    63	 * program timing registers, so it may be NULL during command-only tests.
    64	 *
    65	 * init_cmds replaces the default EK79007 sequence when non-NULL.  A custom
    66	 * sequence is responsible for including its own sleep-exit command and any
    67	 * required delay.
