   132	{
   133	  struct esp_mipi_dsi_video_dma_config_s config;
   134	  FAR void *frame_buffer;
   135	  int ret;
   136	
   137	  if (panel == NULL || !panel->created || panel->host == NULL)
   138	    {
   139	      return -EINVAL;
