   156	  config.hactive = panel->config.hactive;
   157	  config.hsync = panel->config.hsync;
   158	  config.hback_porch = panel->config.hback_porch;
   159	  config.hfront_porch = panel->config.hfront_porch;
   160	  config.vactive = panel->config.vactive;
   161	  config.vsync = panel->config.vsync;
