   167	  config.input_format = panel->config.input_format;
   168	  config.output_format = panel->config.output_format;
   169	  config.frame_buffer = frame_buffer;
   170	  config.frame_buffer_bytes = panel->frame_buffer_bytes;
   171	
   172	  ret = esp_mipi_dsi_dma_buffer_sync_for_device(
