 129	 ****************************************************************************/
 130	
 131	static void dsi_probe_fill_rgb565_colour_bars(FAR uint16_t *frame_buffer,
 132	                                              uint16_t width,
 133	                                              uint16_t height)
 134	{
 135	  static const uint16_t g_colours[] =
 136	  {
 137	    0xffff, /* White */
 138	    0xffe0, /* Yellow */
 139	    0x07ff, /* Cyan */
 140	    0x07e0, /* Green */
 141	    0xf81f, /* Magenta */
 142	    0xf800, /* Red */
 143	    0x001f, /* Blue */
 144	    0x0000, /* Black */
 145	  };
 146	
 147	  uint32_t x;
 148	  uint32_t y;
 149	  uint32_t bar;
 150	
 151	  for (y = 0; y < height; y++)
 152	    {
 153	      for (x = 0; x < width; x++)
 154	        {
 155	          bar = x * (sizeof(g_colours) / sizeof(g_colours[0])) / width;
 156	          frame_buffer[y * width + x] = g_colours[bar];
 157	        }
 158	    }
 159	}
