 163	 ****************************************************************************/
 164	
 165	static int dsi_probe_run_video_pattern(FAR struct mipi_dsi_host *host,
 166	                                       FAR struct ek79007_panel_s *panel,
 167	                                       unsigned int seconds)
 168	{
 169	  FAR struct esp_mipi_dsi_dpi_panel_s *dpi_panel;
 170	  FAR void *frame_buffer;
 171	  size_t frame_buffer_bytes;
 172	  unsigned int elapsed;
 173	  int display_ret;
 174	  int status_ret;
 175	  int ret;
 176	
 177	  dpi_panel = panel->dpi_panel;
 178	  if (dpi_panel == NULL)
 179	    {
 180	      return -EPIPE;
 181	    }
 182	
 183	  ret = esp_mipi_dsi_dpi_panel_get_frame_buffer(
 184	    dpi_panel, &frame_buffer, &frame_buffer_bytes);
 185	  if (ret < 0)
 186	    {
 187	      return ret;
 188	    }
 189	
 190	  dsi_probe_fill_rgb565_colour_bars(frame_buffer,
 191	                                    dpi_panel->config.hactive,
 192	                                    dpi_panel->config.vactive);
 193	
 194	  ret = ek79007_panel_draw_bitmap(panel, frame_buffer, frame_buffer_bytes);
 195	  if (ret < 0)
 196	    {
 197	      return ret;
 198	    }
 199	
 200	  ret = board_mipi_dsi_backlight_set(true);
 201	  if (ret < 0)
 202	    {
 203	      return ret;
 204	    }
 205	
 206	  printf("dsi_probe: EK79007 DPI RGB565 vertical colour bars active for "
 207	         "%u seconds; "
 208	         "LVGL is not involved\n", seconds);
 209	  printf("dsi_probe: draw_bitmap() submitted; visually confirm colour bars "
 210	         "before recording a display PASS\n");
 211	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-start");
 212	  if (status_ret < 0)
 213	    {
 214	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
 215	             status_ret);
 216	    }
 217	
 218	  for (elapsed = 0; elapsed < seconds; elapsed++)
 219	    {
 220	      ret = nxsig_usleep(1000 * 1000);
 221	      if (ret < 0)
 222	        {
 223	          break;
 224	        }
 225	
 226	      if (elapsed == 0)
 227	        {
 228	          status_ret = board_mipi_dsi_video_dump_status(host,
 229	                                                         "probe-after-1s");
 230	          if (status_ret < 0)
 231	            {
 232	              printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
 233	                     status_ret);
 234	            }
 235	        }
 236	    }
 237	
 238	  status_ret = board_mipi_dsi_video_dump_status(host, "probe-before-stop");
 239	  if (status_ret < 0)
 240	    {
 241	      printf("dsi_probe: DMA status snapshot unavailable ret=%d\n",
 242	             status_ret);
 243	    }
 244	
 245	  display_ret = dsi_probe_panel_shutdown(panel);
 246	  if (display_ret < 0 && ret == OK)
 247	    {
 248	      ret = display_ret;
 249	    }
 250	
 251	  return ret;
 252	}
